mapper.select:
select x.*, lm.name as lmname, s.name as subtypename, t.name as tagname from xinxi x left join lanmu lm on x.lmid=lm.id left join subtype s on x.subtypeid=s.id left join stag t on x.tagid=t.id where 1=1
and x.lmid=#{lmid}
and x.pubren=#{pubren}
and x.state=#{state}
and x.title like '%${keyword}%'
and x.title like '%${title}%'
${order}
limit #{topcount}
